recipes.code:
{
  "inputs": [
    {
      "id": "pagewatch-api-key",
      "type": "promptString",
      "description": "An existing key. Without one, the first call mints a free trial key and returns it.",
      "password": true
    }
  ],
  "servers": {
    "pagewatch": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "pagewatch-mcp@0.1.0"
      ],
      "env": {
        "PAGEWATCH_API_KEY": "${input:pagewatch-api-key}",
        "PAGEWATCH_BASE_URL": "https://pagelens.dev"
      }
    }
  }
}
